*** Begin Patch
*** Update File: /root/local.rules
@@
-# Write your rule(s) here.
-# Requirement: raise exactly sid:1000001 for the custom exfil pattern.
+alert http any any -> any any (
+  msg:"TLM exfil telemetry report";
+  flow:established,to_server;
+
+  http.method;
+  content:"POST";
+  nocase;
+
+  http.uri;
+  pcre:"/^\\/telemetry\\/v2\\/report$/";
+
+  http.header;
+  pcre:"/(^|\\r\\n)X-TLM-Mode\\s*:\\s*exfil(\\r\\n|$)/i";
+
+  http_client_body;
+  pcre:"/(^|[&])blob=[A-Za-z0-9+\\/]{80,}={0,2}/";
+
+  http_client_body;
+  pcre:"/(^|[&])sig=[0-9a-fA-F]{64}(?![0-9a-fA-F])/";
+
+  sid:1000001;
+  rev:1;
+)
*** End Patch

